// Package: Npgsql (for pgvector)
// Minimal vector store abstraction plus a concrete PostgreSQL pgvector implementation.

using Npgsql;
using NpgsqlTypes;
using System.Data;

public interface IVectorStore
{
    Task UpsertAsync(
        IEnumerable<VectorRecord> records,
        CancellationToken ct = default);

    Task<IReadOnlyList<VectorSearchResult>> SearchAsync(
        ReadOnlyMemory<float> queryVector,
        int topK = 5,
        IReadOnlyDictionary<string, object?>? filters = null,
        CancellationToken ct = default);
}

public sealed record VectorRecord(
    string Id,
    string DocumentId,
    int ChunkIndex,
    string Text,
    ReadOnlyMemory<float> Vector,
    IReadOnlyDictionary<string, string?> Metadata);

public sealed record VectorSearchResult(
    VectorRecord Record,
    float Score);

public sealed class PgVectorStore : IVectorStore
{
    private readonly string _connectionString;

    public PgVectorStore(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task UpsertAsync(
        IEnumerable<VectorRecord> records,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(records);

        await using var connection = new NpgsqlConnection(_connectionString);
        await connection.OpenAsync(ct);

        await using var transaction = await connection.BeginTransactionAsync(ct);

        foreach (var record in records)
        {
            await using var cmd = new NpgsqlCommand(
                "INSERT INTO document_chunks (id, document_id, chunk_index, text, embedding) " +
                "VALUES (@id, @documentId, @chunkIndex, @text, @embedding) " +
                "ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text",
                connection,
                transaction);

            cmd.Parameters.AddWithValue("id", record.Id);
            cmd.Parameters.AddWithValue("documentId", record.DocumentId);
            cmd.Parameters.AddWithValue("chunkIndex", record.ChunkIndex);
            cmd.Parameters.AddWithValue("text", record.Text);
            cmd.Parameters.AddWithValue("embedding", NpgsqlDbType.Vector, record.Vector.ToArray());

            await cmd.ExecuteNonQueryAsync(ct);
        }

        await transaction.CommitAsync(ct);
    }

    public async Task<IReadOnlyList<VectorSearchResult>> SearchAsync(
        ReadOnlyMemory<float> queryVector,
        int topK = 5,
        IReadOnlyDictionary<string, object?>? filters = null,
        CancellationToken ct = default)
    {
        var sql = @"SELECT id, document_id, chunk_index, text, 1 - (embedding <=> @query) AS score FROM document_chunks";

        if (filters is { Count: > 0 })
        {
            var whereClauses = new List<string>();
            foreach (var (key, value) in filters)
            {
                if (value is not null)
                {
                    whereClauses.Add($\"metadata->>'{key}' = @{key}\");
                }
            }

            if (whereClauses.Count > 0)
            {
                sql += " WHERE " + string.Join(" AND ", whereClauses);
            }
        }

        sql += " ORDER BY embedding <=> @query LIMIT @topK";

        await using var connection = new NpgsqlConnection(_connectionString);
        await connection.OpenAsync(ct);

        await using var cmd = new NpgsqlCommand(sql, connection);
        cmd.Parameters.AddWithValue("query", NpgsqlDbType.Vector, queryVector.ToArray());
        cmd.Parameters.AddWithValue("topK", topK);

        foreach (var (key, value) in filters ?? new Dictionary<string, object?>())
        {
            if (value is not null)
            {
                cmd.Parameters.AddWithValue(key, value);
            }
        }

        var results = new List<VectorSearchResult>();

        await using var reader = await cmd.ExecuteReaderAsync(ct);
        while (await reader.ReadAsync(ct))
        {
            var vectorArray = reader.GetFieldValue<float[]>(4);
            var vector = new ReadOnlyMemory<float>(vectorArray);
            results.Add(new VectorSearchResult(
                new VectorRecord(
                    reader.GetString(0),
                    reader.GetString(1),
                    reader.GetInt32(2),
                    reader.GetString(3),
                    vector,
                    new Dictionary<string, string?>()),
                reader.GetFloat(5)));
        }

        return results;
    }
}

